param([string]$Executable = 'publish-mazdalink/MazdaLink.exe', [string]$Output = 'release')
$ErrorActionPreference = 'Stop'
$version = ([xml](Get-Content (Join-Path $PSScriptRoot '../Directory.Build.props') -Raw)).Project.PropertyGroup.Version
if ($version -notmatch '^\d+\.\d+\.\d+(?:-[A-Za-z0-9.-]+)?$') { throw 'Invalid release version.' }
$sdk = (Get-Content (Join-Path $PSScriptRoot '../global.json') -Raw | ConvertFrom-Json).sdk.version
$runtime = ([xml](Get-Content (Join-Path $PSScriptRoot '../Directory.Build.props') -Raw)).Project.PropertyGroup.RuntimeFrameworkVersion
$repository = git rev-parse --show-toplevel
if ($LASTEXITCODE -ne 0) { throw 'Cannot locate the repository root.' }
$commit = git -C $repository rev-parse HEAD
if ($LASTEXITCODE -ne 0 -or $commit -notmatch '^[a-f0-9]{40}$') { throw 'Cannot identify release source.' }
git -C $repository diff --quiet HEAD --
if ($LASTEXITCODE -ne 0) { throw 'Tracked source differs from the release commit.' }
$folder = [IO.Path]::GetFullPath($Output)
if (Test-Path -LiteralPath $folder) { throw 'Release destination must be new.' }
New-Item -ItemType Directory -Path $folder | Out-Null
Copy-Item -LiteralPath $Executable -Destination (Join-Path $folder 'MazdaLink.exe')
$archiveName = "MazdaLink-v$version-source.zip"
$archive = Join-Path $folder $archiveName
git -C $repository archive --format=zip --prefix=MazdaLink/ -o $archive HEAD
if ($LASTEXITCODE -ne 0) { throw 'Source archive failed.' }
& (Join-Path $PSScriptRoot 'Verify-SourceArchive.ps1') -Archive $archive -Repository $repository -Commit $commit -Prefix 'MazdaLink/'
$hashes = @{}
foreach ($name in @('MazdaLink.exe', $archiveName)) { $hashes[$name] = (Get-FileHash -LiteralPath (Join-Path $folder $name) -Algorithm SHA256).Hash.ToLowerInvariant() }
$manifest = [ordered]@{ schemaVersion=17; version=$version; tag="v$version"; sourceCommit=$commit; sdk=$sdk; runtime=$runtime; architecture='win-x86'; applicationInterface='WindowsForms'; defaultLaunch='desktop'; terminalSwitch='--terminal'; desktopFramework='Microsoft.WindowsDesktop.App'; desktopFrameworkVersion=$runtime; files=$hashes; ecuProgrammingEnabled=$true; programmingFamily='ZYJ2-ZYC3-detached-spare-EB14-EB15'; readIdentityPolicy='reported-calibration'; checksumSoftwareId='ZY87EC000ZYV5050'; additionalChecksumSoftwareId='ZYJ2EA000ZYV5050'; zyj2EditableStart=0xC0100; zyj2EditableEndExclusive=0xE0000; modifiedRomPlan='ZYJ2-offline-EB14-EB15-difference-only'; eb15WritingImplemented=$true; eb15OriginalRestoreQualification='ZYJ2EA000ZYV5050-original-EB15-only'; eb15OriginalRestoreKernelSha256='59a08f914f848badd851ee139b416859d2b7ee80873d5ee2b53dbeb848ade4f6'; eb15OriginalRestoreKernelBytes=3012; eb15OriginalRestoreHardwareAcceptance='unqualified'; eb15ColdRecoveryHardwareAcceptance='unqualified'; eb15ModifiedWritingImplemented=$true; eb15ControlledRecoveryCheck='ZYJ2EA000ZYV5050-EB15-completed-unit-zero-boundary'; eb15ControlledRecoveryHardwareAcceptance='unqualified'; eb15ControlledRecoveryStopUnits=1; eb15ControlledRecoveryRequiresOriginalRestorationEvidence=$true; eb15ControlledRecoveryErasesBootValidityPointer=$true; eb15ControlledRecoveryResumePolicy='exact-boundary-fresh-erase-only'; benchRecoveryCheck='ZYJ2EA000ZYV5050-identification-only'; realEcuAcceptance='unqualified'; ramSelfTest='ZYJ2EA000ZYV5050-fixed-volatile-only'; ramSelfTestHardwareAcceptance='unqualified'; ramSelfTestImageSha256='34bd2a95b30d2a34f8ccc6ccc5e3486cac2d7ecc5f8c31720e7a0a2594c1cad0'; protectedFlashInitialization='ZYJ2EA000ZYV5050-fixed-protected-only'; protectedInitializationHardwareAcceptance='unqualified'; protectedInitializationImageSha256='85ccb46064aa483d64f53b5666017b57b2624ea015fcae0299ef5f336587925b'; recoveryBindingCheck='ZYJ2EA000ZYV5050-preserved-boot-read-only'; recoveryBindingHardwareAcceptance='unqualified'; recoveryBindingPreservedBytes=28928; writeEnableControl='ZYJ2EA000ZYV5050-fixed-gpio-only'; writeEnableControlHardwareAcceptance='unqualified'; writeEnableControlImageSha256='5d6a904f85c225e12f29d171fcc1c1a88fc1bd27ac55ee5a35083b73909326c9'; recoveryRehearsal='ZYJ2EA000ZYV5050-fixed-initialization-ram-service'; recoveryRehearsalHardwareAcceptance='unqualified'; recoveryRehearsalImageSha256='3d6d56b24d9e2629418beda03b40cc436d168cd47bf33754c759a7c6a00f1623'; originalRestorePlan='ZYJ2EA000ZYV5050-original-EB14-offline-only'; nativeTransactionTrial='ZYJ2EA000ZYV5050-fixed-read-ram-stage-only'; nativeTransactionHardwareAcceptance='unqualified'; nativeTransactionImageSha256='1bc447e0e18e168767b16d7c7b1d7204b3e9d95cbcc3b8206b1d553dc8073c3f'; nativeTransactionImageBytes=2036; nativeFlashCandidate='original-only-qualification'; originalRestoreTransaction='unchanged-original-durable-intent-qualification'; originalRestoreQualification='ZYJ2EA000ZYV5050-original-EB14-only'; originalRestoreHardwareAcceptance='unqualified'; originalRestoreKernelSha256='64e9d433dfd752f28195537a97c1afe80f938c6ea9af1217f162a4a22a37d430'; originalRestoreKernelBytes=3012; modifiedFlashingEnabled=$true; interruptedRecoveryQualified=$false; modifiedSpareFlash='ZYJ2EA000ZYV5050-ZYC3-only'; modifiedSpareRecovery='original-both-blocks-fresh-cold-full-erase'; modifiedSpareHardwareAcceptance='unqualified'; goodEcuFlashingEnabled=$false; modifiedFlashBlockOrder='EB14-then-EB15-same-monitor-session'; modifiedFlashJournalSchema=1; modifiedFlashInitialImage='supported-calibration-with-valid-checksums'; controlledRecoveryCheck='ZYJ2EA000ZYV5050-completed-unit-zero-boundary'; controlledRecoveryHardwareAcceptance='unqualified'; controlledRecoveryStopUnits=1; activeFlashPowerCutImplemented=$false; controlledRecoveryRequiresOriginalRestorationEvidence=$true }
$manifest | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $folder 'release.json') -Encoding utf8NoBOM
$hashes['release.json'] = (Get-FileHash -LiteralPath (Join-Path $folder 'release.json') -Algorithm SHA256).Hash.ToLowerInvariant()
@($hashes.Keys | Sort-Object | ForEach-Object { "$($hashes[$_])  $_" }) | Set-Content -LiteralPath (Join-Path $folder 'SHA256SUMS.txt') -Encoding utf8NoBOM
Write-Output "Packaged exact source commit $commit for v$version."
